style.css:
css
body {
  background-color: #e6f2e6; /* sanftes Grün */
  color: #1a1a1a; /* dunkles Grau für Text */
  font-family: 'Arial', sans-serif;
}

a {
  color: #4d88ff; /* weiches Blau für Links */
}

h1, h2, h3 {
  color: #336633; /* dunkleres Grün für Überschriften */
}

* {
  transition: all 0.3s ease;
}
